<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import { ElMessage } from "element-plus";
import { createProject, createProjectEntry, createWbs, listProjectEntries, listProjects } from "../../api/phase2";
type Row=Record<string,any>; const rows=ref<Row[]>([]); const entries=ref<Row[]>([]); const loading=ref(false); const visible=ref(false); const entryVisible=ref(false); const selected=ref<Row|null>(null); const form=reactive({project_code:"",name:"",customer_id:"",budget_amount:0,start_date:"",end_date:""}); const entry=reactive({project_id:"",wbs_id:"",entry_date:"",category:"expense",source_type:"manual",source_id:"",amount:0});
function unwrap(r:any){if(r?.data?.code!==0)throw new Error(r?.data?.msg||"接口返回失败");return r.data.data} async function load(){loading.value=true;try{rows.value=unwrap(await listProjects())||[]}catch(e){ElMessage.error(e instanceof Error?e.message:"项目加载失败")}finally{loading.value=false}} function openCreate(){Object.assign(form,{project_code:"",name:"",customer_id:"",budget_amount:0,start_date:"",end_date:""});visible.value=true} async function save(){if(!form.project_code.trim()||!form.name.trim()){ElMessage.warning("请填写项目编码和名称");return}try{unwrap(await createProject({...form}));ElMessage.success("项目已创建");visible.value=false;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:"项目创建失败")}} async function openEntries(row:Row){selected.value=row;entry.project_id=row.id;try{entries.value=unwrap(await listProjectEntries(row.id))||[];entryVisible.value=true}catch(e){ElMessage.error(e instanceof Error?e.message:"项目成本加载失败")}} async function saveEntry(){if(!entry.entry_date||!entry.source_id.trim()||entry.amount<=0){ElMessage.warning("请填写日期、来源单据和金额");return}try{unwrap(await createProjectEntry({...entry}));ElMessage.success("项目成本已归集");await openEntries(selected.value!);await load()}catch(e){ElMessage.error(e instanceof Error?e.message:"项目成本归集失败")}} onMounted(load);
</script>
<template><section class="page-stack"><header class="page-heading"><div><small>PROJECT / COST CONTROL</small><h1>项目与成本控制中心</h1><p>以项目/WBS 为主线归集采购、工时、库存、收入和费用，显示预算、实际和利润风险。</p></div><el-space><el-button type="primary" @click="openCreate">新建项目</el-button><el-button :loading="loading" @click="load">刷新</el-button></el-space></header><el-card shadow="never"><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="project_code" label="项目编码" width="150"/><el-table-column prop="name" label="项目名称" min-width="220"/><el-table-column prop="budget_amount" label="预算"/><el-table-column prop="actual_amount" label="实际"/><el-table-column prop="variance" label="预算余额"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="120"><template #default="scope"><el-button link type="primary" @click="openEntries(scope.row)">查看成本</el-button></template></el-table-column><template #empty><el-empty description="暂无项目"/></template></el-table></el-card><el-dialog v-model="visible" title="新建项目" width="560px"><el-form label-width="90px"><el-form-item label="项目编码" required><el-input v-model="form.project_code"/></el-form-item><el-form-item label="项目名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="客户 ID"><el-input v-model="form.customer_id"/></el-form-item><el-form-item label="预算金额"><el-input-number v-model="form.budget_amount" :min="0" :precision="2"/></el-form-item><el-form-item label="起止日期"><el-date-picker v-model="form.start_date" value-format="YYYY-MM-DD"/><el-date-picker v-model="form.end_date" value-format="YYYY-MM-DD"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-drawer v-model="entryVisible" title="项目成本明细" size="620px"><el-button type="primary" @click="entryVisible=true">新增成本</el-button><el-table :data="entries" stripe><el-table-column prop="entry_date" label="日期"/><el-table-column prop="category" label="类别"/><el-table-column prop="source_type" label="来源"/><el-table-column prop="source_id" label="来源单据"/><el-table-column prop="amount" label="金额"/></el-table><el-divider/><el-form label-width="80px"><el-form-item label="归集日期"><el-date-picker v-model="entry.entry_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="类别"><el-select v-model="entry.category"><el-option v-for="item in ['purchase','labor','inventory','revenue','expense']" :key="item" :value="item" :label="item"/></el-select></el-form-item><el-form-item label="来源单据"><el-input v-model="entry.source_id"/></el-form-item><el-form-item label="金额"><el-input-number v-model="entry.amount" :min="0.01"/></el-form-item><el-button type="primary" @click="saveEntry">归集成本</el-button></el-form></el-drawer></section></template>
<style scoped>.page-stack{display:flex;flex-direction:column;gap:16px}.page-heading{display:flex;justify-content:space-between;align-items:flex-end}.page-heading small{color:var(--erp-muted-text);letter-spacing:.08em}.page-heading h1{margin:4px 0}.page-heading p{margin:0;color:var(--erp-muted-text)}</style>
